<?php $edit=isset($record['id']);$val=fn($key)=>e($record[$key]??'');?><div class="admin-pagehead"><div><span class="micro-label">RELATOS Y ACONTECIMIENTOS</span><h1><?= $edit?'Editar historia':'Nueva historia' ?></h1><p>Registra acontecimientos auténticos, fechas y fotografías autorizadas.</p></div><a class="btn btn-outline" href="/admin/historias">← Historias</a></div><div class="animal-editor-grid"><section class="admin-panel"><form class="editor-form" method="post" action="<?= $edit?'/admin/historias/'.(int)$record['id'].'/editar':'/admin/historias' ?>"><?= csrf_field() ?><label>Animal relacionado *<select name="animal_id" required><option value="">Seleccionar</option><?php foreach($animals as $a):?><option value="<?= (int)$a['id'] ?>" <?= ($record['animal_id']??'')==$a['id']?'selected':'' ?>><?= e($a['nombre']) ?> · #<?= (int)$a['id'] ?></option><?php endforeach ?></select></label><label>Título *<input name="titulo" required maxlength="150" value="<?= $val('titulo') ?>"></label><div class="form-pair"><label>Fecha del evento *<input type="date" name="fecha_evento" required value="<?= $val('fecha_evento') ?>"></label><label>Etapa<select name="estado_proceso"><?php foreach(['rescate','primera_valoracion','traslado','tratamiento','recuperacion','disponible_adopcion','adopcion','otro'] as $v):?><option value="<?= $v ?>" <?= ($record['estado_proceso']??'otro')===$v?'selected':'' ?>><?= e(str_replace('_',' ',$v)) ?></option><?php endforeach ?></select></label></div><label>Relato *<textarea rows="9" name="descripcion" required><?= $val('descripcion') ?></textarea></label><label class="toggle-row"><input type="checkbox" name="publicada" value="1" <?= !empty($record['publicada'])?'checked':'' ?>><span>Mostrar en el sitio público</span></label><label class="toggle-row"><input type="checkbox" name="contenido_verificado" value="1"><span>Verifiqué la información y tengo autorización para publicarla.</span></label><button class="btn btn-primary" type="submit">Guardar historia ↗</button></form></section><aside class="admin-panel"><h2>Galería de esta historia</h2><?php if(!$edit):?><p>Guarda la historia para añadir imágenes.</p><?php else: ?><div class="photo-gallery"><?php foreach($photos as $photo):?><img src="<?= e(asset($photo['ruta'])) ?>" alt="<?= e($photo['texto_alternativo']) ?>" loading="lazy"><?php endforeach ?></div><form class="upload-form" method="post" enctype="multipart/form-data" action="/admin/historias/<?= (int)$record['id'] ?>/foto"><?= csrf_field() ?><label>Fotografía<input data-preview-image type="file" name="foto" accept="image/jpeg,image/png,image/webp" required></label><img hidden class="upload-preview" alt="Vista previa"><label>Texto alternativo<input name="texto_alternativo" maxlength="150"></label><button class="btn btn-outline">Subir foto ↥</button></form><?php endif ?></aside></div>
